    std::mt19937 motor{59};
    std::uniform_int_distribution<int> elegir{-2, 4};
    std::vector<int> datos;
    for (int i{0}; i < 16; ++i) {
        datos.push_back(elegir(motor));
    }
    bool dentro = true;
    for (int dato : datos) {
        dentro = dentro && dato >= -2 && dato <= 4;
    }
    std::cout << "Quantité:" << datos.size() << '\n';
    std::cout << "Dans l'intervalle:" << dentro;
    return 0;
}

